test('mergeCustomers merges two customers successfully', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', issueDate: '2026-10-07', number: 'INV-001' },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.customers[0].id, 'C-002');
});

